def _vp_goal_unit(goal, pose):
    if "x" in goal:
        dx, dz = float(goal["x"]) - pose.x, float(goal["z"]) - pose.z
    else:
        dx, dz = float(goal["ux"]), float(goal["uz"])
    length = math.hypot(dx, dz)
    return (dx / length, dz / length) if length else (0.0, 0.0)

